-- Sharpet quiz app — Supabase schema (with EN/DE/CS translations)
-- Run this once in your Supabase project's SQL Editor (Database > SQL Editor > New query)
-- If you already ran an earlier version of this file, drop the old tables first:
--   drop table if exists quiz_answers, quiz_sessions, reported_questions, friendships,
--     question_translations, questions, domain_translations, domains, profiles cascade;

-- ============================================================
-- 1. DOMAINS (language-independent core row + per-language name)
-- ============================================================
create table if not exists domains (
  id serial primary key,
  color text default '#4FD1FF'
);

create table if not exists domain_translations (
  domain_id int references domains(id) on delete cascade,
  language_code text not null check (language_code in ('en','de','cs')),
  name text not null,
  primary key (domain_id, language_code)
);

