-- ============================================================
-- 2. QUESTIONS (language-independent core + per-language text/options)
-- ============================================================
create table if not exists questions (
  id serial primary key,
  domain_id int references domains(id) on delete cascade,
  correct_index int not null,   -- index into options, same across all languages
  is_active boolean default true,
  created_at timestamptz default now()
);

create table if not exists question_translations (
  question_id int references questions(id) on delete cascade,
  language_code text not null check (language_code in ('en','de','cs')),
  text text not null,
  options jsonb not null,   -- e.g. ["FTP","SFTP","SMTP","ICMP"], 2-4 items, same order across languages
  primary key (question_id, language_code)
);

