-- ============================================================
-- 3. PROFILES
-- ============================================================
create table if not exists profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  preferred_language text default 'en' check (preferred_language in ('en','de','cs')),
  created_at timestamptz default now()
);

create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, split_part(new.email, '@', 1));
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- ============================================================
-- 4. QUIZ SESSIONS + ANSWERS (registered users only)
-- ============================================================
create table if not exists quiz_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade not null,
  domain_ids int[] not null,
  language_code text default 'en',
  num_answer_options int not null,
  num_questions int not null,
  correct_count int default 0,
  total_answered int default 0,
  started_at timestamptz default now(),
  ended_at timestamptz
);

create table if not exists quiz_answers (
  id uuid primary key default gen_random_uuid(),
  session_id uuid references quiz_sessions(id) on delete cascade not null,
  question_id int references questions(id) not null,
  selected_index int not null,
  is_correct boolean not null,
  answered_at timestamptz default now()
);

-- ============================================================
-- 5. REPORTED QUESTIONS
-- ============================================================
create table if not exists reported_questions (
  id uuid primary key default gen_random_uuid(),
  question_id int references questions(id) not null,
  user_id uuid references auth.users(id),
  language_code text default 'en',
  reason text,
  resolved boolean default false,
  created_at timestamptz default now()
);

-- ============================================================
-- 6. FRIENDSHIPS
-- ============================================================
create table if not exists friendships (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade not null,
  friend_id uuid references auth.users(id) on delete cascade not null,
  status text check (status in ('pending','accepted')) default 'pending',
  created_at timestamptz default now(),
  unique (user_id, friend_id)
);

-- ============================================================
-- 7. ROW LEVEL SECURITY
-- ============================================================
alter table domains enable row level security;
alter table domain_translations enable row level security;
alter table questions enable row level security;
alter table question_translations enable row level security;
alter table profiles enable row level security;
alter table quiz_sessions enable row level security;
alter table quiz_answers enable row level security;
alter table reported_questions enable row level security;
alter table friendships enable row level security;

drop policy if exists "domains are publicly readable" on domains;
create policy "domains are publicly readable" on domains for select using (true);
drop policy if exists "domain translations are publicly readable" on domain_translations;
create policy "domain translations are publicly readable" on domain_translations for select using (true);
drop policy if exists "active questions are publicly readable" on questions;
create policy "active questions are publicly readable" on questions for select using (is_active = true);
drop policy if exists "question translations are publicly readable" on question_translations;
create policy "question translations are publicly readable" on question_translations
  for select using (exists (select 1 from questions q where q.id = question_id and q.is_active = true));

drop policy if exists "profiles are publicly readable" on profiles;
create policy "profiles are publicly readable" on profiles for select using (true);
drop policy if exists "users can update own profile" on profiles;
create policy "users can update own profile" on profiles for update using (auth.uid() = id);

drop policy if exists "users manage own sessions" on quiz_sessions;
create policy "users manage own sessions" on quiz_sessions
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

drop policy if exists "users manage own answers" on quiz_answers;
create policy "users manage own answers" on quiz_answers
  for all using (
    exists (select 1 from quiz_sessions s where s.id = session_id and s.user_id = auth.uid())
  ) with check (
    exists (select 1 from quiz_sessions s where s.id = session_id and s.user_id = auth.uid())
  );

drop policy if exists "anyone can report a question" on reported_questions;
create policy "anyone can report a question" on reported_questions for insert with check (true);

drop policy if exists "users see own friendships" on friendships;
create policy "users see own friendships" on friendships
  for select using (auth.uid() = user_id or auth.uid() = friend_id);
drop policy if exists "users create friend requests" on friendships;
create policy "users create friend requests" on friendships
  for insert with check (auth.uid() = user_id);
drop policy if exists "users respond to friend requests" on friendships;
create policy "users respond to friend requests" on friendships
  for update using (auth.uid() = friend_id);
